def solve(s: str) -> int:
    """Convert a Roman numeral to an integer.
    Supports standard symbols I, V, X, L, C, D, M with subtractive notation.
    """
    if not s:
        return 0
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        v = values[s[i]]
        # Look ahead to see if a subtractive pair
        if i + 1 < n and values[s[i + 1]] > v:
            total += values[s[i + 1]] - v
            i += 2
        else:
            total += v
            i += 1
    return total

