def solve(matrix):
    """Return elements of matrix in clockwise spiral order.
    Handles empty matrix and non‑square rectangular matrices.
    """
    if not matrix:
        return []
    res = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        # top row
        for j in range(left, right + 1):
            res.append(matrix[top][j])
        top += 1
        # right column
        for i in rectangular_range(top, bottom + 1):
            res.append(matrix[i][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for j in range(right, left - 1, -1):
                res.append(matrix[bottom][j])
            bottom -= 1
        if left <= right:
            # left column
            for i in rectangular_range(bottom, top - 1, -1):
                res.append(matrix[i][left])
            left += 1
    return res

# Helper to handle range with start > end gracefully (include if start==end)
def rectangular_range(start, end, step=1):
